import { existsSync, mkdtempSync, realpathSync, rmSync, statfsSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
const EXHAUSTION_MARKER = "SANDBOX EXHAUSTED -- THE HOST, NOT THE CODE UNDER TEST";
const EXHAUSTION_CODES = Object.freeze({
    ENOSPC: "the filesystem holding the sandbox root is full",
    EDQUOT: "this user's disk quota on that filesystem is exhausted",
    EACCES: "the sandbox root could not be written to"
});
const CAPACITY_PHRASES = Object.freeze({
    ENOSPC: "No space left on device",
    EDQUOT: "Disk quota exceeded"
});
const BYTES_PER_KIB = 1024;
const BYTES_PER_MIB = BYTES_PER_KIB * BYTES_PER_KIB;
const BYTES_PER_GIB = BYTES_PER_MIB * BYTES_PER_KIB;
function exhaustionCause(error) {
    const failure = error ?? {};
    const code = "string" == typeof failure.code ? failure.code : "";
    if (code in EXHAUSTION_CODES) return code;
    const text = `${asText(failure.message)}\n${asText(failure.stderr)}`;
    for (const name of Object.keys(CAPACITY_PHRASES))if (text.includes(name) || text.includes(CAPACITY_PHRASES[name])) return name;
    return null;
}
function describeSandboxExhaustion(error, { root, cause, statfs = statfsSync }) {
    const meaning = EXHAUSTION_CODES[cause] ?? `${cause} while building the sandbox`;
    const original = firstLine(asText((error ?? {}).message)) ?? "the setup threw with no message";
    return `${EXHAUSTION_MARKER}: ${cause} building the test sandbox ${root} -- ${meaning}. ${freeSpace(root, statfs)}. Free space on that filesystem and re-run; this run proved nothing about the code under test. The original error was: ${original}`;
}
function sandboxExhaustionError(error, root) {
    const cause = exhaustionCause(error);
    if (null === cause) return null;
    const described = new Error(describeSandboxExhaustion(error, {
        root,
        cause
    }), {
        cause: error
    });
    described.name = "SandboxExhaustionError";
    return described;
}
function withSandbox({ prefix, base = tmpdir() }, body) {
    const intended = join(base, prefix);
    let root = "";
    try {
        root = realpathSync(mkdtempSync(intended));
        return body(root);
    } catch (error) {
        throw sandboxExhaustionError(error, "" === root ? intended : root) ?? error;
    } finally{
        if ("" !== root) rmSync(root, {
            recursive: true,
            force: true
        });
    }
}
function buildSandbox({ prefix, base = tmpdir() }, populate) {
    const intended = join(base, prefix);
    let root = "";
    try {
        root = realpathSync(mkdtempSync(intended));
        populate(root);
        return root;
    } catch (error) {
        if ("" !== root) rmSync(root, {
            recursive: true,
            force: true
        });
        throw sandboxExhaustionError(error, "" === root ? intended : root) ?? error;
    }
}
function freeSpace(root, statfs) {
    const measured = existingAncestor(root);
    try {
        const { bsize, blocks, bavail } = statfs(measured);
        return `${humanBytes(bavail * bsize)} free of ${humanBytes(blocks * bsize)} on the filesystem holding ${measured}`;
    } catch (error) {
        return `its filesystem free space could not be read at ${measured} (${firstLine(asText((error ?? {}).message)) ?? "no message"})`;
    }
}
function existingAncestor(path) {
    let current = path;
    for(;;){
        if (existsSync(current)) return current;
        const parent = dirname(current);
        if (parent === current) return current;
        current = parent;
    }
}
function humanBytes(bytes) {
    if (bytes >= BYTES_PER_GIB) return `${(bytes / BYTES_PER_GIB).toFixed(1)} GiB`;
    if (bytes >= BYTES_PER_MIB) return `${(bytes / BYTES_PER_MIB).toFixed(1)} MiB`;
    return `${bytes} B`;
}
function asText(value) {
    if (null == value) return "";
    return "string" == typeof value ? value : String(value);
}
function firstLine(text) {
    const line = text.split("\n")[0].trim();
    return "" === line ? null : line;
}
export { EXHAUSTION_CODES, EXHAUSTION_MARKER, buildSandbox, describeSandboxExhaustion, exhaustionCause, sandboxExhaustionError, withSandbox };
